mapper.select:
SELECT /* LGUTLC00120.retrieveMenuTreeList */ menu_id , menu_name , system_code , module_code , high_menu_id , program_id , program_name , url_addr as menu_url_addr , menu_level_no , sort_order_no , display_flag , pop_up_screen_flag FROM LGCOM_MENU_M_V WHERE system_code = #{systemCode} AND display_flag = 'Y' AND language_code = #{USER_SESSION.languageCode}
AND module_code = #{moduleCode}
ORDER BY menu_order_by

mapper.delete:
DELETE FROM /* LGUTLC00120.deleteManualData */
            LGCOM_PROGRAM_USE_HELP_N
      WHERE program_id    = #{manualProgramId}
        AND language_code = #{manualLanguageCode}

mapper.update:
UPDATE /* LGUTLC00120.updateManualAttachFileId */
       LGCOM_PROGRAM_USE_HELP_N
   SET etc_attach_file_id = NULL
     , last_updated_by    = #{USER_SESSION.applicationUserId}
     , last_update_date   = SYSDATE
  WHERE program_id        = #{manualProgramId}
    AND language_code     = #{manualLanguageCode}
